`timescale 1ns / 1ps
// Latency-arbitrage protocol, addresses and the hardcoded fair path.
//
// Prices are integer ticks: 1 tick = $0.01, so $100.00 = 10000.
// The PC quotes 2-wide: bid = fair - 1, ask = fair + 1.
// F only goes long: it buys a stale ask when fair - ask > SPREAD (2 ticks).
//
// Fair path: arithmetic Brownian motion, seed 1, sigma = 80 ticks/sqrt(s),
// waits ~U(1 s, 2 s). Generated by gen_fair_path.py; do not hand-edit the
// arrays. DELAY_DIV scales the waits (50_000 = 1 ms of wait per clock, for
// simulation).

package lat_arb_pkg;

  localparam int CLK_HZ    = 50_000_000;
  localparam int UDP_PORT  = 5000;
  localparam int MAX_PAY   = 32;
  localparam int SPREAD    = 2;
  localparam int HALF_SP   = 1;
  localparam logic [15:0] QUOTE_SZ = 16'd1;

  localparam logic [47:0] E_MAC = 48'h02_00_00_00_00_02;
  localparam logic [47:0] P_MAC = 48'h02_00_00_00_00_01;
  localparam logic [47:0] F_MAC = 48'h02_00_00_00_00_03;
  localparam logic [31:0] E_IP  = {8'd192, 8'd168, 8'd10, 8'd2};
  localparam logic [31:0] P_IP  = {8'd192, 8'd168, 8'd10, 8'd1};
  localparam logic [31:0] F_IP  = {8'd192, 8'd168, 8'd10, 8'd3};

  localparam logic [7:0] SRC_E = 8'd0;
  localparam logic [7:0] SRC_F = 8'd1;
  localparam logic [7:0] SRC_P = 8'd2;

  localparam logic [7:0] T_ORDER  = 8'd1;
  localparam logic [7:0] T_FILL   = 8'd2;
  localparam logic [7:0] T_BOOK   = 8'd3;
  localparam logic [7:0] T_FAIR   = 8'd5;
  localparam logic [7:0] T_CANCEL = 8'd6;
  localparam logic [7:0] T_ACK    = 8'd7;

  localparam logic [7:0] SIDE_B = 8'd0;
  localparam logic [7:0] SIDE_S = 8'd1;
  localparam logic [7:0] TIF_REST = 8'd0;
  localparam logic [7:0] TIF_IOC  = 8'd1;

  localparam logic [7:0] ACK_ACCEPTED       = 8'd0;
  localparam logic [7:0] ACK_FILLED         = 8'd1;
  localparam logic [7:0] ACK_NO_FILL        = 8'd2;
  localparam logic [7:0] ACK_CANCEL_OK      = 8'd3;
  localparam logic [7:0] ACK_CANCEL_TOO_LATE = 8'd4;
  localparam logic [7:0] ACK_BAD_ORDER      = 8'd5;

  // Header (4) + payload.
  localparam int LEN_ORDER  = 16; // 4 + 4+1+1+4+2
  localparam int LEN_FILL   = 22; // 4 + 4+4+2+8
  localparam int LEN_BOOK   = 24; // 4 + 4+2+4+2+8
  localparam int LEN_FAIR   = 18; // 4 + 2+4+8
  localparam int LEN_CANCEL = 8;  // 4 + 4
  localparam int LEN_ACK    = 9;  // 4 + 4+1

  // seed=1, start $100.00, 16 jumps. Index 0 is the opening fair.
  localparam int N_FAIR = 17;
  localparam logic [31:0] FAIR_MS [0:N_FAIR-1] = '{
    32'd0,    32'd1134, 32'd1255, 32'd1495, 32'd1789,
    32'd1094, 32'd1433, 32'd1762, 32'd1722, 32'd1229,
    32'd1031, 32'd1025, 32'd1381, 32'd1217, 32'd1222,
    32'd1438, 32'd1231
  };
  localparam logic [31:0] FAIR_PX [0:N_FAIR-1] = '{
    32'd10000, 32'd10083, 32'd9958,  32'd9823,  32'd9871,
    32'd10028, 32'd10060, 32'd10175, 32'd10177, 32'd10357,
    32'd10298, 32'd10113, 32'd10056, 32'd10037, 32'd10047,
    32'd9977,  32'd9979
  };

  function automatic logic [31:0] fair_clks(input int delay_div, input int i);
    logic [63:0] prod;
    prod = 64'(FAIR_MS[i]) * 64'(CLK_HZ / 1000);
    if (delay_div <= 1)
      return prod[31:0];
    return 32'(prod / 64'(delay_div));
  endfunction

  function automatic logic [15:0] ip_csum(input logic [15:0] total_len,
                                          input logic [31:0] src,
                                          input logic [31:0] dst);
    logic [31:0] s;
    s = 32'h4500 + 32'(total_len) + 32'h4011
      + 32'(src[31:16]) + 32'(src[15:0])
      + 32'(dst[31:16]) + 32'(dst[15:0]);
    s = {16'd0, s[15:0]} + {16'd0, s[31:16]};
    s = {16'd0, s[15:0]} + {16'd0, s[31:16]};
    return ~s[15:0];
  endfunction

endpackage
